python - <<'PY' 2>/dev/null || node -e "
const fs=require('fs');let s=fs.readFileSync('src/components/ArticleBody.tsx','utf8');
s=s.replace(\"import type { Block } from '../data/posts';\",\"import { TAG_LABELS, type Block, type Post } from '../data/posts';\");
s=s.replace('function renderBlock(block: Block, index: number) {','function renderBlock(post: Post, block: Block, index: number) {');
