s=s.replace('className=\"muted small\" data-testid=\"figure-caption\"','className=\"fig\" data-testid=\"figure-caption\"');
s=s.replace('{block.cite && <figcaption className=\"muted small\">','{block.cite && <figcaption className=\"quote-cite\">');
s=s.replace('export default function ArticleBody({ blocks }: { blocks: Block[] }) {','/** 1-based position of a figure among the post\\'s figures. */\nfunction figureNumber(post: Post, index: number) {\n  return post.body.slice(0, index + 1).filter((block) => block.type === \\'figure\\').length;\n}\n\nexport default function ArticleBody({ post }: { post: Post }) {');
s=s.replace('{blocks.map(renderBlock)}','{post.body.map((block, index) => renderBlock(post, block, index))}');
fs.writeFileSync('src/components/ArticleBody.tsx',s);"
